            meaning: "27 നക്ഷത്രങ്ങളും ആദി, മധ്യ, അന്ത്യ എന്നീ മൂന്ന് നാഡികളിൽ ഒന്നിൽ പെടുന്നു; പരമ്പരാഗത ഭാരതീയ ചിന്തയിലെ മൂന്ന് പ്രകൃതങ്ങളെയാണ് ഇവ സൂചിപ്പിക്കുന്നത്. രണ്ട് നക്ഷത്രങ്ങളും വ്യത്യസ്ത നാഡികളിലായിരിക്കണമെന്നാണ് നാഡി പൊരുത്തം ആവശ്യപ്പെടുന്നത്; പരസ്പരം പൂരകമായ രണ്ട് സ്വഭാവങ്ങളായാണ് ഇത് വായിക്കുന്നത്. തമിഴ്, കേരള ജാതക റിപ്പോർട്ടുകൾ ഇത് പത്തിനൊപ്പം അച്ചടിക്കാറുണ്ട്.",
            reason: (bs, gs, bn, gn, ok) => `${bs}: ${bn} നാഡി. ${gs}: ${gn} നാഡി. രണ്ട് നക്ഷത്രങ്ങളും വ്യത്യസ്ത നാഡികളിലാണെങ്കിൽ പൊരുത്തമുണ്ട്; ${ok ? "അതിനാൽ പൊരുത്തമുണ്ട്." : "അതിനാൽ പൊരുത്തമില്ല."}`,
            match: "നിങ്ങളുടെ നക്ഷത്രങ്ങൾ വ്യത്യസ്ത നാഡികളിലാണ്; പരസ്പരം പൂരകമായ രണ്ട് സ്വഭാവങ്ങളായാണ് പാരമ്പര്യം ഇതിനെ കാണുന്നത്.",
            notMatch: "നാഡി പൊരുത്തമില്ല. പരമ്പരാഗത ഗ്രന്ഥങ്ങൾ ഇതിനെ ഗൗരവമായി കാണുന്നു; ഇതിന് പാരമ്പര്യത്തിൽ ഒഴിവുകളുണ്ട്, അവ ഈ ആപ്പ് പരിശോധിക്കുന്നില്ല — അറിവുള്ള ഒരു ജ്യോതിഷിയുമായി സംസാരിക്കുന്നത് നല്ലതാണ്.",
